/**
 * #236 LIVE PUBLIC browser acceptance from a static local Astro build.
 * Four real PDF pages use non-origin CropBox, /Rotate 0/90/180/270, transparent
 * painted regions, and a magenta drawing explicitly outside the crop boundary.
 * Independently render each with node PDF.js + @napi-rs/canvas, decode with
 * Sharp, compare pixels to actual browser downloads, and reopen ZIP via Python
 * stdlib zipfile. No OCR, server PDF engine, cloud, Gold, or physical-device QA.
 *
 * VIDEO/PDF builds are never regenerated by this script. Set PDF236_DIST to
 * an existing static tree; PDF236_BROWSERS=chromium[,firefox,webkit].
 */
import { chromium, firefox, webkit } from "@playwright/test";
import assert from "node:assert/strict";
import { spawn, execFileSync } from "node:child_process";
import { mkdtempSync, writeFileSync, readFileSync, rmSync, existsSync } from "node:fs";
import { resolve, join } from "node:path";
import { tmpdir } from "node:os";
import { getDocument } from "pdfjs-dist/legacy/build/pdf.mjs";
import { createCanvas } from "@napi-rs/canvas";
import sharp from "sharp";
import { makeRotatedCropPdf236, PDF_236_PAGE_ROTATIONS } from "../tests/fixtures/pdf-rotated-236-corpus.mjs";

const root = resolve(import.meta.dirname, "..");
const dist = resolve(process.env.PDF236_DIST ?? resolve(root, "../Strumentini.it/dist"));
const port = Number(process.env.PDF236_PORT ?? 18566);
const origin = `http://127.0.0.1:${port}`;
const available = { chromium, firefox, webkit };
const browsers = (process.env.PDF236_BROWSERS ?? "chromium,firefox,webkit").split(",").map((item) => item.trim());
assert(Number.isInteger(port) && port >= 1024 && port <= 65535, "Invalid loopback port");
assert(browsers.length > 0 && browsers.every((item) => Object.hasOwn(available, item)), "Invalid browser selection");
assert(existsSync(join(dist, "tools/pdf-to-images/index.html")), "No current static PDF→images route: refusing nonexistent browser success");
const corpus = makeRotatedCropPdf236();
const background = "#15304d";
const backgroundRgb = [21, 48, 77];

async function rawRgba(bytes) {
  const image = sharp(bytes);
  const info = await image.metadata();
  const { data, info: decoded } = await image.ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  assert.equal(decoded.channels, 4);
  return { pixels: data, width: decoded.width, height: decoded.height, format: info.format };
}

async function independentReference() {
  const loading = getDocument({ data: new Uint8Array(corpus), useSystemFonts: false });
  const document = await loading.promise;
  assert.equal(document.numPages, 4);
  const pages = new Map();
  try {
    for (const scale of [0.5, 1, 1.5]) {
      for (let number = 1; number <= 4; number += 1) {
        const page = await document.getPage(number);
        try {
          assert.equal(page.rotate, PDF_236_PAGE_ROTATIONS[number - 1]);
          assert.deepEqual(page.view, [20, 30, 200, 130]);
          const viewport = page.getViewport({ scale });
          const width = Math.ceil(viewport.width);
          const height = Math.ceil(viewport.height);
          const widthExpected = (number % 2 === 0 ? 100 : 180) * scale;
          const heightExpected = (number % 2 === 0 ? 180 : 100) * scale;
          assert.deepEqual([width, height], [widthExpected, heightExpected]);
          const canvas = createCanvas(width, height);
          const context = canvas.getContext("2d");
          await page.render({ canvas, canvasContext: context, viewport, background }).promise;
          const image = await rawRgba(canvas.toBuffer("image/png"));
          assert.deepEqual([...image.pixels.subarray(0, 3)], backgroundRgb, "Reference corner not alpha flattened to background");
          const painted = new Set();
          for (let i = 0; i < image.pixels.length; i += 4) {
            if (Math.abs(image.pixels[i] - backgroundRgb[0]) + Math.abs(image.pixels[i + 1] - backgroundRgb[1]) + Math.abs(image.pixels[i + 2] - backgroundRgb[2]) > 40) {
              painted.add(`${image.pixels[i]},${image.pixels[i + 1]},${image.pixels[i + 2]}`);
            }
          }
          assert(painted.size > 2, "Page fixture did not render multiple colors including transparency");
          pages.set(`${number}/${scale}`, image);
          canvas.width = canvas.height = 0;
        } finally { page.cleanup(); }
      }
    }
  } finally {
    await loading.destroy();
  }
  return pages;
}

function pixelDifference(actual, expected, isJpeg) {
  assert.deepEqual([actual.width, actual.height], [expected.width, expected.height]);
  let totalError = 0;
  let maxError = 0;
  let nonBackground = 0;
  let alphaWrong = 0;
  let nearMagenta = 0;
  for (let i = 0; i < actual.pixels.length; i += 4) {
    for (let color = 0; color < 3; color += 1) {
      const delta = Math.abs(actual.pixels[i + color] - expected.pixels[i + color]);
      totalError += delta;
      maxError = Math.max(delta, maxError);
    }
    if (actual.pixels[i + 3] !== 255) alphaWrong += 1;
    if (Math.abs(actual.pixels[i] - backgroundRgb[0]) + Math.abs(actual.pixels[i + 1] - backgroundRgb[1]) + Math.abs(actual.pixels[i + 2] - backgroundRgb[2]) > 50) nonBackground += 1;
    if (actual.pixels[i] > 245 && actual.pixels[i + 1] < 12 && actual.pixels[i + 2] > 245) nearMagenta += 1;
  }
  const mae = totalError / (actual.width * actual.height * 3);
  assert(mae <= (isJpeg ? 14 : 2.5), `Independent PDF.js/Sharp pixel error too large: MAE=${mae.toFixed(2)} max=${maxError}`);
  assert.equal(alphaWrong, 0, "Source transparency not flattened onto raster background");
  assert(nonBackground >= 30, "Exported page contains no painted content");
  // The magenta out-of-CropBox square may not leak into any page, including
  // page 4 whose internal shape is purple but not the (255,0,255) marker.
  assert.equal(nearMagenta, 0, "Off-CropBox magenta artwork leaked into raster");
  return { mae: Number(mae.toFixed(3)), nonBackground, dimensions: [actual.width, actual.height] };
}

function reopenZipPython(path, expectedPaths) {
  const code = String.raw`
import sys,zipfile,hashlib
archive = sys.argv[1]
paths=sys.argv[2:]
with zipfile.ZipFile(archive) as z:
    assert z.namelist() == [p.split('/')[-1] for p in paths], (z.namelist(),paths)
    for path in paths:
        contents=z.read(path.split('/')[-1]); plain=open(path,'rb').read()
        assert contents == plain and len(contents)>24
print('PYTHON_ZIPFILE_236_REOPEN_PASS entries=%d bytes_identical=true'%len(paths))
`;
  return execFileSync("python3", ["-c", code, path, ...expectedPaths], { encoding: "utf8", timeout: 10000 }).trim();
}

async function downloaded(page, filename, temporary) {
  const pending = page.waitForEvent("download");
  await page.getByRole("link", { name: `Scarica ${filename}`, exact: true }).click();
  const actualDownload = await pending;
  assert.equal(actualDownload.suggestedFilename(), filename);
  const bytes = readFileSync(await actualDownload.path());
  const destination = join(temporary, filename);
  writeFileSync(destination, bytes);
  return { bytes, destination };
}

async function setupPage(context, offsite, errors) {
  const page = await context.newPage();
  page.on("pageerror", (err) => errors.push(String(err)));
  await page.route("**/*", (route) => {
    const url = route.request().url();
    if (url.startsWith(`${origin}/`) || url.startsWith("blob:") || url.startsWith("data:")) return route.continue();
    offsite.push(url);
    return route.abort();
  });
  const response = await page.goto(`${origin}/tools/pdf-to-images/`, { waitUntil: "networkidle" });
  assert.equal(response?.status(), 200);
  return page;
}

async function submit(page, options, expectedState = "success") {
  await page.locator('form input[type="file"]').first().setInputFiles({ name: "crop-rotate-alpha-236.pdf", mimeType: "application/pdf", buffer: corpus });
  await page.getByLabel("Pagine (facoltativo)").fill(options.pages);
  await page.getByLabel("Formato uscita").selectOption(options.mime);
  await page.getByLabel("Scala render").fill(String(options.scale));
  await page.getByLabel("Sfondo raster").fill(background);
  await page.locator('form button[type="submit"]').first().click();
  await page.locator(`.result-panel[data-state="${expectedState}"]`).waitFor({ timeout: 25000 });
}

async function waitForServer() {
  for (let n = 0; n < 75; n += 1) {
    try { if ((await fetch(`${origin}/tools/pdf-to-images/`)).status === 200) return; } catch {}
    await new Promise((done) => setTimeout(done, 120));
  }
  throw new Error("Unable to start local static server");
}

const baseline = await independentReference();
const temp = mkdtempSync(join(tmpdir(), "pdf-rotated-236-"));
const server = spawn("python3", ["-m", "http.server", String(port), "--bind", "127.0.0.1", "--directory", dist], { stdio: "ignore" });
let checks = 0;
try {
  await waitForServer();
  for (const name of browsers) {
    const browser = await available[name].launch({ headless: true });
    const context = await browser.newContext({ viewport: { width: 390, height: 844 }, acceptDownloads: true });
    const offsite = [];
    const errors = [];
    try {
      const page = await setupPage(context, offsite, errors);
      const pngOrder = [2, 4, 1, 3];
      await submit(page, { pages: "2,4,1,3", mime: "image/png", scale: 1 });
      const paths = [];
      const pixelResults = [];
      for (const number of pngOrder) {
        const filename = `page-${String(number).padStart(3, "0")}.png`;
        const file = await downloaded(page, filename, temp);
        assert.deepEqual([...file.bytes.subarray(0, 8)], [137, 80, 78, 71, 13, 10, 26, 10], "Downloaded bytes do not have PNG signature");
        const image = await rawRgba(file.bytes);
        assert.equal(image.format, "png");
        pixelResults.push({ page: number, ...pixelDifference(image, baseline.get(`${number}/1`), false) });
        paths.push(file.destination);
        checks += 5;
      }
      const archive = await downloaded(page, "pdf-pages.zip", temp);
      assert(archive.bytes.subarray(0, 2).toString() === "PK", "Downloaded ZIP signature invalid");
      console.log(`${name}: ${reopenZipPython(archive.destination, paths)}`);
      checks += 5;
      // PDF.js rotation and CropBox make page geometry alternate between
      // 180x100 and 100x180, not the 240x160 MediaBox.
      assert.deepEqual(pixelResults.map((item) => item.dimensions), [[100, 180], [100, 180], [180, 100], [180, 100]]);
      checks += 4;

      // Genuine JPEG exports with 0.5x => effective 36 DPI. No ZIP for one page.
      for (const number of [2, 3]) {
        await submit(page, { pages: String(number), mime: "image/jpeg", scale: 0.5 });
        const filename = `page-${String(number).padStart(3, "0")}.jpg`;
        const file = await downloaded(page, filename, temp);
        assert.equal(file.bytes[0], 255); assert.equal(file.bytes[1], 216);
        assert.equal(file.bytes.at(-2), 255); assert.equal(file.bytes.at(-1), 217);
        const image = await rawRgba(file.bytes);
        assert.equal(image.format, "jpeg");
        const measured = pixelDifference(image, baseline.get(`${number}/0.5`), true);
        assert.equal(await page.getByRole("link", { name: "Scarica pdf-pages.zip" }).count(), 0);
        checks += 6;
        console.log(`${name}: JPEG page=${number} 36DPI ${measured.dimensions.join("x")} MAE=${measured.mae}`);
      }

      // Pixel dimensions at 1.5x (=108 effective DPI), with alpha flattening.
      await submit(page, { pages: "1", mime: "image/png", scale: 1.5 });
      const highDpi = await downloaded(page, "page-001.png", temp);
      assert.deepEqual(pixelDifference(await rawRgba(highDpi.bytes), baseline.get("1/1.5"), false).dimensions, [270, 150]);
      checks += 4;

      for (const invalid of ["2,2", "4-1", "5", "1,,2"]) {
        await page.getByLabel("Pagine (facoltativo)").fill(invalid);
        await page.locator('form button[type="submit"]').first().click();
        await page.locator('.result-panel[data-state="error"]').waitFor({ timeout: 15000 });
        assert.equal(await page.getByRole("link", { name: /Scarica page-|Scarica pdf-pages.zip/u }).count(), 0,
          `${name}: stale image artifact after invalid ${invalid}`);
        checks += 2;
      }

      // Exercise the real AbortSignal while a browser PNG encode is pending.
      // Hold one native toBlob callback without synthesizing output, cancel
      // via the public button, then release the original browser encoder.
      await page.evaluate(() => {
        const actualToBlob = HTMLCanvasElement.prototype.toBlob;
        window.__pdf236PendingEncodes = [];
        window.__pdf236RestoreEncode = () => { HTMLCanvasElement.prototype.toBlob = actualToBlob; };
        HTMLCanvasElement.prototype.toBlob = function(callback, mime, quality) {
          window.__pdf236PendingEncodes.push({ canvas: this, callback, mime, quality });
        };
      });
      await page.getByLabel("Pagine (facoltativo)").fill("1,2");
      await page.getByLabel("Formato uscita").selectOption("image/png");
      await page.getByLabel("Scala render").fill("1");
      await page.locator('form button[type="submit"]').first().click();
      await page.waitForFunction(() => window.__pdf236PendingEncodes.length > 0, null, { timeout: 15000 });
      await page.getByRole("button", { name: "Annulla", exact: true }).click();
      await page.evaluate(() => {
        window.__pdf236RestoreEncode();
        for (const request of window.__pdf236PendingEncodes) {
          HTMLCanvasElement.prototype.toBlob.call(request.canvas, request.callback, request.mime, request.quality);
        }
      });
      await page.locator('.result-panel[data-state="cancelled"]').waitFor({ timeout: 15000 });
      assert.equal(await page.getByRole("link", { name: /Scarica page-|Scarica pdf-pages.zip/u }).count(), 0,
        `${name}: cancelled export exposed an incomplete output`);
      checks += 3;

      // 25 MiB is the public route's PDF input byte ceiling. A real oversized
      // File should fail before generating a downloadable image or ZIP.
      const oversized = Buffer.alloc(25 * 1024 * 1024 + 1);
      corpus.copy(oversized);
      await page.locator('form input[type="file"]').first().setInputFiles({
        name: "too-large-236.pdf", mimeType: "application/pdf", buffer: oversized,
      });
      await page.locator('form button[type="submit"]').first().click();
      await page.locator('.result-panel[data-state="error"]').waitFor({ timeout: 15000 });
      assert.equal(await page.getByRole("link", { name: /Scarica page-|Scarica pdf-pages.zip/u }).count(), 0,
        `${name}: oversized PDF emitted a downloadable artifact`);
      checks += 2;
      const layout = await page.evaluate(() => ({ width: document.documentElement.clientWidth, scroll: document.documentElement.scrollWidth }));
      assert(layout.scroll <= layout.width + 2, `390px horizontal overflow ${JSON.stringify(layout)}`);
      assert.deepEqual(offsite, [], "Offsite network traffic");
      assert.deepEqual(errors, [], "Browser unhandled JS errors");
      checks += 3;
      console.log(`${name} #236 PNG/ZIP/JPEG/DPI/rotation/crop/alpha browser PASS ${JSON.stringify({ pixelResults, viewport: 390, offsite: 0, errors: 0 })}`);
      await page.close();
    } finally {
      await context.close();
      await browser.close();
    }
  }
  console.log(`PDF236_ROTATED_BROWSER_PASS checks=${checks} browsers=${browsers.join(",")} independent=pdfjs-napi-sharp-python-zipfile`);
} finally {
  if (server.exitCode === null) server.kill("SIGTERM");
  rmSync(temp, { recursive: true, force: true });
}
